INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('c127d16f-6f40-59e0-9078-b49a96fb1a9a', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 7, 7, 'According to Lenz''s law, what is the direction of an induced current?', NULL, 1, 'multiple_choice'::answer_type, 'Such that its magnetic field opposes the change in flux that produces it', NULL, false, NULL, false, NULL, 'The induced current always opposes the change causing it. Mark scheme (1 mark). B1: C (Such that its magnetic field opposes the change in flux that produces it).', 1, NULL, NULL),
('ae5c18b4-44b0-51d9-88bc-0b14ad275597', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 8, 8, 'The north pole of a magnet is pulled away from a coil. What pole forms at the end of the coil nearest the magnet?', NULL, 1, 'multiple_choice'::answer_type, 'A south pole, which attracts the magnet and opposes its removal', NULL, false, NULL, false, NULL, 'Opposing the decrease in flux means trying to hold the magnet back. Mark scheme (1 mark). B1: A (A south pole, which attracts the magnet and opposes its removal).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 230" role="img" aria-labelledby="fg488f545c-t fg488f545c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg488f545c-t">Magnet pulled away from a coil</title><desc id="fg488f545c-d">A bar magnet with its north pole nearest a coil is pulled away from the coil; the coil is connected to a galvanometer.</desc><rect x="24" y="77" width="60" height="36" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="84" y="77" width="60" height="36" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="54" y="95" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:700">S</text><text x="114" y="95" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:700">N</text><path d="M233.6,61 A6,34 0 0,0 233.6,129" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M233.6,61 A6,34 0 0,1 233.6,129" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M250.7,61 A6,34 0 0,0 250.