none;stroke-linecap:round;stroke-linejoin:round"/><line x1="345" y1="129" x2="345" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="225" y1="190" x2="273" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="297" y1="190" x2="345" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="285" cy="190" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="285" y="190.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">G</text><line x1="40" y1="55" x2="121.7" y2="55" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="128,55 119.8,58.8 119.8,51.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="84" y="39" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">push against 0.20 N</text><polygon points="150,43 156.3,40 156.3,46" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="154.9" y1="43" x2="265.1" y2="43" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="270,43 263.7,46 263.7,40" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="31" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">15 cm</text></svg>', 'A bar magnet is pushed towards and 15 cm into a coil connected to a galvanometer, against an average repulsive force of 0.20 N.'),
('5d30639b-b46b-54e4-b3e7-f69644589320', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 10, 10, 'Where does the electrical energy produced by electromagnetic induction come from?', NULL, 1, 'multiple_choice'::answer_type, 'From the work done against the opposing magnetic force', NULL, false, NULL, false, NULL, 'Lenz''s law ensures that work must be done, as energy conservation requires. Mark scheme (1 mark). B1: D (From the work done against the opposing magnetic force).', 1, NULL, NULL),
('fccbec54-3783-5f48-84f1-7b7e8fecf23c', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 11, 11, 'An induced current of 2.0 A flows in a 0.30 m rod at right angles to a 0.40 T field. Calculate the magnetic force that opposes the rod''s motion.', NULL, 1, 'numeric'::answer_type, '0.24', 'N', false, NULL, false, NULL, 'F = BIL = 0.40 × 2.0 × 0.30 = 0.24 N. Mark scheme (2 marks). C1: F = BIL. A1: F = 0.24 N.', 2, NULL, NULL),
('cb08bc14-02f0-54ba-97ce-3109858bad49', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 12, 12, 'In Fleming''s right-hand rule (the dynamo rule), what does the thumb represent?', NULL, 1, 'multiple_choice'::answer_type, 'The direction of motion of the conductor', NULL, false, NULL, false, NULL, 'Thumb: motion; first finger: field; second finger: induced current. Mark scheme (1 mark). B1: B (The direction of motion of the conductor).', 1, NULL, NULL),
('21ed4fd5-98ee-5684-ad39-c95afb32f13f', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 13, 13, 'A rod is pushed at a constant 5.0 m s⁻¹ against an opposing magnetic force of 0.24 N. Calculate the power needed.', NULL, 1, 'numeric'::answer_type, '1.2', 'W', false, NULL, false, NULL, 'P = Fv = 0.24 × 5.0 = 1.2 W. Mark scheme (2 marks). C1: P = Fv. A1: P = 1.2 W.', 2, NULL, NULL),
('1435043a-d7d4-55d9-8a47-e9becfcf5133', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 14, 14, 'An aluminium ring rests on top of a coil wound round a vertical iron core. When the current in the coil is switched on, the ring jumps up. Why?', NULL, 1, 'multiple_choice'::answer_type, 'The induced current in the ring produces a field that opposes the growing flux, so the ring is repelled', NULL, false, NULL, false, NULL, 'Lenz''s law: the ring''s field opposes the increase in flux. Mark scheme (1 mark). B1: C (The induced current in the ring produces a field that opposes the growing flux, so the ring is repelled).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 280" role="img" aria-labelledby="fg87ec7e26-t fg87ec7e26-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg87ec7e26-t">Jumping ring</title><desc id="fg87ec7e26-d">An aluminium ring rests around a vertical iron core above a coil wound on the core. The coil is connected to a supply through a switch, which is open.</desc><rect x="104" y="30" width="32" height="230" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><path d="M86,175.7 A34,6 0 0,1 154,175.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,175.7 A34,6 0 0,0 154,175.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,187.1 A34,6 0 0,1 154,187.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,187.1 A34,6 0 0,0 154,187.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,198.6 A34,6 0