b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="76,190 73,183.7 79,183.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="70" y="139" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.80 m</text><line x1="182" y1="194" x2="250" y2="194" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="182" y1="266" x2="250" y2="266" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="250" y1="194" x2="250" y2="218" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="250" y1="242" x2="250" y2="266" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="250" cy="230" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="230.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">G</text></svg>', 'A 0.050 kg magnet is released from rest 0.80 m above a coil connected to a galvanometer and falls through it.'),
('c66dc415-35f3-50f2-8cd6-f4d8913ac3f0', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '4ac2239b-8226-4bfc-8116-0d8626521f30', 'a-level', '26.4', '9702 coursebook 26.4 · Lenz''s law', 38, 38, 'An aluminium ring with a narrow cut in it is placed on a coil that is switched on. What happens?', NULL, 2, 'multiple_choice'::answer_type, 'It does not jump, because no current can circulate round the ring', NULL, false, NULL, false, NULL, 'An e.m.f. is induced, but the cut stops the current, so there is no opposing field. Mark scheme (3 marks). C1: e.m.f. but no current. C1: no force. A1: B (It does not jump, because no current can circulate round the ring).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 280" role="img" aria-labelledby="fg2a8317a8-t fg2a8317a8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2a8317a8-t">Ring with a cut</title><desc id="fg2a8317a8-d">An aluminium ring with a narrow cut in it rests around a vertical iron core above a coil, which is connected to a supply through a switch.</desc><rect x="104" y="30" width="32" height="230" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><path d="M86,175.7 A34,6 0 0,1 154,175.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,175.7 A34,6 0 0,0 154,175.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,187.1 A34,6 0 0,1 154,187.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,187.1 A34,6 0 0,0 154,187.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,198.6 A34,6 0 0,1 154,198.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,198.6 A34,6 0 0,0 154,198.6" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,210 A34,6 0 0,1 154,210" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,210 A34,6 0 0,0 154,210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,221.4 A34,6 0 0,1 154,221.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,221.4 A34,6 0 0,0 154,221.4" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,232.9 A34,6 0 0,1 154,232.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,232.9 A34,6 0 0,0 154,232.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,244.3 A34,6 0 0,1 154,244.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M86,244.3 A34,6 0 0,0 154,244.3" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M90,90 A30,8 0 0,0 144,95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M90,90 A30,8 0 0,1 150,90" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M150,90 A30,8 0 0,1 148,92" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="160" y="82" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">aluminium ring (cut)</text><text x="144" y="44" font-si