('bc5ae5a7-d84a-57e1-b142-af6898db335b', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '24d540aa-65ef-46d8-ac39-5c62ee4aed70', 'a-level', '26.5', '9702 coursebook 26.5 · Everyday examples of electromagnetic induction', 7, 7, 'A transformer has 1200 turns on its primary and 60 on its secondary. The primary is connected to 240 V a.c. Calculate the secondary voltage.', NULL, 1, 'numeric'::answer_type, '12', 'V', false, NULL, false, NULL, 'Vₛ = Vₚ × Nₛ/Nₚ = 240 × 60 ÷ 1200 = 12 V. Mark scheme (2 marks). C1: Vₛ/Vₚ = Nₛ/Nₚ. A1: Vₛ = 12 V.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 250" role="img" aria-labelledby="fg1e564524-t fg1e564524-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1e564524-t">Step-down transformer</title><desc id="fg1e564524-d">A transformer: 1200 primary turns connected to a 240 V a.c. supply, and 60 secondary turns connected to a load.</desc><path d="M150,46 a6,6 0 0,1 6,-6 h138 a6,6 0 0,1 6,6 v148 a6,6 0 0,1 -6,6 h-138 a6,6 0 0,1 -6,-6 Z M180,70 h90 v100 h-90 Z" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:var(--fig-fill,rgba(29,78,216,0.10));fill-rule:evenodd;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="90" x2="184" y2="96" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="100" x2="184" y2="106" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="110" x2="184" y2="116" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="120" x2="184" y2="126" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="130" x2="184" y2="136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="140" x2="184" y2="146" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="150" x2="184" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="90" x2="100" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="156" x2="100" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="90" x2="100" y2="111" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="135" x2="100" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="100" cy="123" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M93,123 q3.5,-7 7,0 t7,0" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="123" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor">240 V a.c.</text><line x1="266" y1="90" x2="304" y2="96" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266" y1="100" x2="304" y2="106" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266" y1="110" x2="304" y2="116" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266" y1="120" x2="304" y2="126" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266" y1="130" x2="304" y2="136" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266" y1="140" x2="304" y2="146" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266" y1="150" x2="304" y2="156" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="304" y1="90" x2="370" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="304" y1="156" x2="370" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="90" x2="370" y2="105" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="141" x2="370" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="363" y="105" width="14" height="36" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="165" y="222" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Nₚ = 1200</text><text x="285" y="222" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Nₛ = 60</text></svg>', 'A transformer: 1200 primary turns connected to a 240 V a.c. supply, and 60 secondary turns connected to a load.'),
('479b2947-e3e9-506e-9b82-f2991b6f0e27', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '24d540aa-65ef-46d8-ac39-5c62ee4aed70', 'a-level', '26.5', '9702 coursebook 26.5 · Everyday examples of electromagnetic induction', 8, 8, 'How does a step-down transformer differ from a step-up transformer?', NULL, 1, 'multiple_choice'::answer_type, 'It has fewer turns on the secondary than on the primary', NULL, false, NULL, false, NULL, 'Vₛ/Vₚ = Nₛ/Nₚ, so fewer secondary turns give a lower output voltage. Mark scheme (1 mark). B1: C (It has fewer turns on the secondary than on the primary).', 1, NULL, NULL),
('1efa6872-4b79-5203-b3c3-0eb268731420', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '24d540aa-65ef-46d8-ac39-5c62ee4aed70', 'a-level', '26.5', '9702 coursebook 26.5 · Everyday examples of electromagnetic induction', 9, 9, 'A phone charger transformer steps 230 V down to 5.0 V. Calculate the turns ratio Nₚ/Nₛ.', NULL, 1, 'numeric'::answer_type, '46', NULL, false, NULL, false, NULL, 'Nₚ/Nₛ = Vₚ/Vₛ = 230 ÷ 5.0 = 46. Mark scheme (2 marks). C1: turns ratio = voltage ratio. A1: Nₚ/Nₛ = 46.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 250" role="img" aria-labelledby="fgecaf121e-t fgecaf121e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgecaf121e-t">Charger transformer</title><desc id="fgecaf121e-d">A transformer with a 230 V a.c. supply across the primary and an output of 5.0 V across the secondary.</desc><path d="M150,46 a6,6 0 0,1 6,-6 h138 a6,6 0 0,1 6,6 v148 a6,6 0 0,1 -6,6 h-138 a6,6 0 0,1 -6,-6 Z M180,70 h90 v100 h-90 Z" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:var(--fig-fill,rgba(29,78,216,0.10));fill-rule:evenodd;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="90" x2="184" y2="96" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="100" x2="184" y2="106" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="110" x2="184" y2="116" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="120" x2="184" y2="126" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="130" x2="184" y2="136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="146" y1="140" x2="184" y2="146" style="stroke:currentColor;stroke-width:2.0;