('1d8ac783-f10c-5a0b-8a56-fb267c63825d', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '24d540aa-65ef-46d8-ac39-5c62ee4aed70', 'a-level', '26.5', '9702 coursebook 26.5 · Everyday examples of electromagnetic induction', 22, 22, 'Why does a bicycle dynamo lamp glow more brightly when the bicycle goes faster?', NULL, 1, 'multiple_choice'::answer_type, 'The magnet turns faster, so the flux changes more quickly and the e.m.f. is larger', NULL, false, NULL, false, NULL, 'E depends on the rate of change of flux linkage. Mark scheme (1 mark). B1: B (The magnet turns faster, so the flux changes more quickly and the e.m.f. is larger).', 1, NULL, NULL),
('7a9dacae-e29b-538a-83d1-3cc5a1cda4a2', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '24d540aa-65ef-46d8-ac39-5c62ee4aed70', 'a-level', '26.5', '9702 coursebook 26.5 · Everyday examples of electromagnetic induction', 23, 23, 'Power stations send 10 MW along a line at 400 kV. Calculate the current in the line.', NULL, 1, 'numeric'::answer_type, '25', 'A', false, NULL, false, NULL, 'I = P/V = 10 × 10⁶ ÷ 400 × 10³ = 25 A. Mark scheme (2 marks). C1: I = P/V. A1: I = 25 A.', 2, NULL, NULL),
('82d626f6-e771-5d07-a66e-2b74b67f4d57', 'f7ead7fd-7729-4ec2-9a2e-7a00cfac7c96', '24d540aa-65ef-46d8-ac39-5c62ee4aed70', 'a-level', '26.5', '9702 coursebook 26.5 · Everyday examples of electromagnetic induction', 24, 24, '10 MW is transmitted along a line of resistance 5.0 Ω at 25 kV. Calculate the power wasted in the line.', NULL, 2, 'numeric'::answer_type, '8e5', 'W', false, NULL, false, NULL, 'I = 10 × 10⁶ ÷ 25 × 10³ = 400 A. P = I²R = 400² × 5.0 = 8.0 × 10⁵ W. Mark scheme (3 marks). C1: I = P/V. C1: P = I²R. A1: P = 8.0 × 10⁵ W.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fgfec56aa8-t fgfec56aa8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfec56aa8-t">Transmission line</title><desc id="fgfec56aa8-d">Circuit: a 25 kV supply sending 10 MW through a transmission line of resistance 5.0 Ω to the consumers.</desc><line x1="26" y1="48" x2="67.4" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="103.4" y1="48" x2="144.8" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="67.4" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="85.4" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">line 5.0 Ω</text><line x1="144.8" y1="48" x2="191.4" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="227.4" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="191.4" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="209.4" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">consumers</text><line x1="26" y1="142" x2="138" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="162" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="150" cy="142" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M143,142 q3.5,-7 7,0 t7,0" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">25 kV</text><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Circuit: a 25 kV supply sending 10 MW through a transmission line of resistance 5.0 Ω to the consumers.'),
